    words: "C1 (a) reads as a launch call: a call by a launcher's own name (spawn, spawnSync, execFile, execFileSync, exec, execSync or fork); a call through an import specifier or a destructuring element renaming one, or through a const bound to a launcher's name or to a member naming one; a member call naming a launcher, by name or by literal key (a string or a no-substitution template); and an execve member call on the identifier process. It is an rf launch when its command words (C1-COMMAND-WORDS) include rf, read as path:declaration:launcher, the declaration being the one function or method declaration around it, else the module-level const bound to an arrow or function expression it sits in, else <module>. It claims that reading exactly at the forms its rows plant, each in its row's reading alone (exactly the one module its row plants and no other, at its row's path and exactly as its row writes it, byte for byte): (1) a call by each launcher's own name (with C1-COMMAND-WORDS (4)), its callee bare and behind parentheses, as, satisfies, !, a type assertion and await; (2) an import specifier renaming one by name from node:child_process and from another module, and by a string name from node:child_process; (3) a const declaration's object destructuring element renaming one by name off require(\"node:child_process\") and off an identifier, and by a string key off require(\"node:child_process\"); (4) a const bound to a launcher's bare name, to a child_process namespace member by name and by literal key, and to another identifier's member by name; (5) a member call by name under a child_process namespace, another identifier, a property access of an identifier, a call of an identifier with no arguments, an element access of an identifier by string key and this, and by literal key under a child_process namespace and another identifier; (6) an execve member call on process by name and by literal key, and none under another identifier; (7) the declaration exactly as its rows write it, byte for byte: a module-level function declaration with no modifier, with export alone and with export and async, none a generator; a method with no modifier and no generator marker in a module-level class declaration with and without export, in a class expression that initializes an exported module-level const and in an object literal that initializes a module-level const with and without export; a module-level const, with and without export, bound to an arrow with a block body that is not async and to a function expression with no name that is neither async nor a generator; an arrow const nested in a module-level function declaration with export alone (read as the function); and <module>; (8) the gate members' plants, byte for byte: P8 to P11 and P13 of refusal #7 (a const bound to a launcher's name, a member call under a nested receiver, a destructuring element off a helper object, an import alias from a launcher module of its own, and a launcher's name behind parentheses and as); and (9) the gate members' plants, byte for byte: P14 to P20 of refusal #8 (a launcher member by a no-substitution template key, an optional member call, a member call reached through optional chaining, a member call under a call of a member, a member call under an element access keyed by a name, and a launch in an object literal's method and in a module-level const arrow that is not exported). Every other route is NOT CLAIMED by this census: an alias bound by let, var or using, by a parameter, a nested pattern or an element with a default value, or read through a wrapper; a member call under any other receiver, a call of another callee or with arguments and an element access by another key among them, other than as P17 and P18 write it; optional chaining (?.) on a call or a member access other than as P15 and P16 write it; every other declaration form, a launch with more than one function or method declaration around it, a function declaration off module level or with a generator marker, a method with a modifier (static or async among them) or a generator marker, a method of a class or object literal off module level, or of a class expression or object literal that initializes no module-level const (one passed as an argument among them), a module-level const bound to an async arrow or to an async or generator function expression, a function or method declaration whose name is no identifier and a module-level let or var bound to an arrow or function expression among them; and a route that combines two of (1) to (7) other than as a row of this census plants it. Each of those forms in every other reading - one with a module its row does not plant beside its row's module, before or after it (one that holds no launch, load, reference, registration, child_process or diagnostics_channel text among them), and one with a module at another path or written otherwise than its row writes it - is NOT CLAIMED by this census.",
