    id: "C1-COMMAND-WORDS",
    pin: "C1",
    words: "C1 (a) reads a launch's command words from its first argument and from each element that is no spread of its second argument when that argument, read through parentheses, as, satisfies, !, a type assertion and await, is an array literal: the words of every text alternative the landed reader reads there (its alternatives(), C1-NAME-RESOLUTION), each split by its commandWords(); an opaque alternative (a name that does not resolve, a template or + join with a part that does not resolve) gives no word. It claims that reading exactly at the launch forms its rows plant, each in its row's reading alone (exactly the one module its row plants and no other, at its row's path and exactly as its row writes it, byte for byte): (1) a first argument that is a string, a no-substitution template, a const it resolves (a shadowing const; a shadowed one gives no word), a let or an unbound name it does not resolve, a template or + join whose every part resolves or one with a part that does not, either side of ?: / ?? / ||, a shell line (whitespace, &&, a directory path and a .exe suffix) or a program with no rf word, under the launcher each row names, and the element at index 0 of an env launch's array as each of those forms but an unbound name and a shell line, with a shell line at index 1 of a sh launch's array (whitespace alone; whitespace, &&, a directory path and a .exe suffix); (2) a string element at index 0, 1, 2 and 3 of an env launch's array; (3) a string element of an env launch's array before, between and after spreads, and a spread holding the word giving none; (4) under each launcher C1-LAUNCH-ROUTES names (spawn, spawnSync, execFile, execFileSync, exec, execSync, fork and process.execve), the first argument and a string element of an env launch's array, and a string element of an env launch's array through an import alias from node:child_process, a destructuring alias off require(\"node:child_process\"), a const alias of a child_process namespace member by name, a member call by name and by literal key, a string and a no-substitution template each, under an identifier, and a child_process namespace member by name and by literal key, a string and a no-substitution template each; (5) a string element of an env launch's array behind parentheses, as const, satisfies, !, a type assertion, await, and parentheses around as const; (6) a string element of the array of a launch whose first argument gives no env or sh word: a nice program and a parameter it does not resolve; and (7) the gate members' plants, byte for byte: P1, P2 and P2b of refusal #5 (a member-route env launch whose rf word is only an argv element - a const, the second side of ?: and the right side of ??), P4 to P7 of refusal #6 (rf after a spread, under execFileSync, behind as const and at index 2) and P12 of refusal #7 (rf an element of a member-route nice launch). Every other launch form is NOT CLAIMED by this census: an element past index 3, another wrapper or a deeper nesting, an element through any other route C1-LAUNCH-ROUTES reads, a launch that combines two of (1) to (6) other than as a row of this census plants it, and every split or drop of commandWords() that no row plants (wb-jwc.10's census is that reader's claim of record). Each of those forms in every other reading - one with a module its row does not plant beside its row's module, before or after it (one that holds no launch, load, reference, registration, child_process or diagnostics_channel text among them), and one with a module at another path or written otherwise than its row writes it - is NOT CLAIMED by this census.",
